/**
 * The review's control and action inventory, reconciled with the current
 * app (plan completion L4, 2026-10-13; review V02, matrix N1). The review
 * listed every interactive JSX control and every action-shaped object in
 * src/ (docs/inventory-baseline.json, baseline `0f4b735a`);
 * `scripts/inventory-scan.mjs` repeats that scan on the current source.
 * Every file the scan finds is classified here, and its controls and
 * actions inherit the class:
 *
 * - `capability`: the controls of these route-ledger rows' views (their
 *   walks are clicked at three sizes by route-ledger.journey.spec.ts).
 * - `primitive`: a shared building block (a menu, a select, a confirm
 *   dialog); its controls belong to whichever capability renders it.
 * - `registry`: an action table read by adapters (the palette, keys,
 *   menus); each of its rows maps to a ledger row through actionDefs.ts.
 * - `harness`: development and test scaffolding, not in the shipped app.
 *
 * Files the baseline had and the app no longer has are `REMOVED`, with
 * why. The command-only surfaces the static scan can't see (chat slash
 * commands, in-surface keys, the native menu) are in `COMMAND_ONLY`, each
 * with its visible route. src/inventoryMap.test.ts holds all of it to the
 * scan; scripts/inventory-reconcile.mjs renders docs/INVENTORY_RECONCILIATION.md.
 *
 * Pure data.
 */

export type InventoryClass = 'capability' | 'primitive' | 'registry' | 'harness';

export interface FileClass {
  class: InventoryClass;
  /** Ledger rows (src/routeLedger.ts ids) its controls belong to. */
  routes?: readonly string[];
  note?: string;
}

const cap = (routes: string[], note?: string): FileClass => ({ class: 'capability', routes, ...(note ? { note } : {}) });
const prim = (note: string): FileClass => ({ class: 'primitive', note });

